}

/**
 * Projekt 5-4_Sportarten
 * 
 * @author Andre Greubel
 * @version 2022-09-12
 */
public class Spieler
{
   private String name; 
   private int trikotnummer;
   private String [] sportarten; 

   public Spieler(String name, int trikotnummer) {
      this.name = name; 
      this.trikotnummer = trikotnummer; 


      sportarten = new String[2];

      sportarten[0] = "Tennis";
      sportarten[1] = "Schwimmen";
   }

   public void nenneSportarten() {
      int i = 0;
      while (i < sportarten.length) {
         System.out.println("Der Spieler" + this.name + " übt die Sportart " + sportarten[i] + " aus.");
         i = i + 1;
      }
   }

    // TODO1
   public void ersetzeSportartTennis() {
      for (int i = 0; i < sportarten.length; i++) {
         if(sportarten[i].equals("Tennis")) {
            sportarten[i] = "Squash";
         }
      }
   }

    // TODO2
   public boolean spieltSportart(String sportart)
   {
      boolean spieltSportart = false;
      for (int i = 0; i < sportarten.length; i++)
      {
         if(sportarten[i].equals(sportart))
         {
            spieltSportart = true;
         }
      }
      return spieltSportart;
   }





   // Hilfsmethode zur Ausgabe - muss nicht verstanden werden
   public String toString() {
      String output = "Name: " + name + " - Trikotnummer: " + trikotnummer + "; Sportarten: ";
      for (int i = 0; i < sportarten.length; i++) {
         output += sportarten[i];
         if(i < sportarten.length - 1) {
            output += ", "; 
         } else {
            output += "; \n";
         }
      }
      return output; 
   }
}

Mannschaft mannschaft = new Mannschaft(); 

Spieler[] spielerliste = mannschaft.gibSpielerListe(); 

for (int i = 0; i < spielerliste.length; i++) {
   print("Spielt Tennis: ");
   println(spielerliste[i].spieltSportart("Tennis"));
   println(spielerliste[i]); 
}

spielerliste[2].ersetzeSportartTennis();

for (int i = 0; i < spielerliste.length; i++) {
